class Solution {
public:
    int minimumCost(string target, vector<string>& words, vector<int>& costs) {
        unordered_map<int, unordered_map<string, int>> by_len;
        for (size_t i = 0; i < words.size(); ++i) {
            int L = words[i].size();
            if (!by_len[L].count(words[i]) || costs[i] < by_len[L][words[i]]) {
                by_len[L][words[i]] = costs[i];
            }
        }
        int n = target.size();
        vector<long long> dp(n + 1, 1e18);
        dp[0] = 0;
        vector<int> lens;
        for (const auto& [L, _] : by_len) lens.push_back(L);
        sort(lens.begin(), lens.end());
        for (int i = 1; i <= n; ++i) {
            for (int L : lens) {
                if (i < L) break;
                if (dp[i - L] != 1e18) {
                    string sub = target.substr(i - L, L);
                    auto it = by_len[L].find(sub);
                    if (it != by_len[L].end()) {
                        dp[i] = min(dp[i], dp[i - L] + it->second);
                    }
                }
            }
        }
        return dp[n] >= 1e18 ? -1 : dp[n];
    }
};

class Solution {
    public int minimumCost(String target, String[] words, int[] costs) {
        Map<Integer, Map<String, Integer>> byLen = new HashMap<>();
        for (int i = 0; i < words.length; ++i) {
            int L = words[i].length();
            byLen.putIfAbsent(L, new HashMap<>());
            Map<String, Integer> m = byLen.get(L);
            if (!m.containsKey(words[i]) || costs[i] < m.get(words[i])) {
                m.put(words[i], costs[i]);
            }
        }
        int n = target.length();
        long[] dp = new long[n + 1];
        Arrays.fill(dp, (long) 1e18);
        dp[0] = 0;
        List<Integer> lens = new ArrayList<>(byLen.keySet());
        Collections.sort(lens);
        for (int i = 1; i <= n; ++i) {
            for (int L : lens) {
                if (i < L) break;
                if (dp[i - L] != (long) 1e18) {
                    String sub = target.substring(i - L, i);
                    Map<String, Integer> m = byLen.get(L);
                    if (m.containsKey(sub)) {
                        dp[i] = Math.min(dp[i], dp[i - L] + m.get(sub));
                    }
                }
            }
        }
        return dp[n] >= (long) 1e18 ? -1 : (int) dp[n];
    }
}

var minimumCost = function(target, words, costs) {
    const byLen = new Map();
    for (let i = 0; i < words.length; ++i) {
        const L = words[i].length;
        if (!byLen.has(L)) byLen.set(L, new Map());
        const m = byLen.get(L);
        if (!m.has(words[i]) || costs[i] < m.get(words[i])) {
            m.set(words[i], costs[i]);
        }
    }
    const n = target.length;
    const dp = new Float64Array(n + 1).fill(Infinity);
    dp[0] = 0;
    const lens = Array.from(byLen.keys()).sort((a, b) => a - b);
    for (let i = 1; i <= n; ++i) {
        for (const L of lens) {
            if (i < L) break;
            if (dp[i - L] !== Infinity) {
                const sub = target.slice(i - L, i);
                const m = byLen.get(L);
                if (m.has(sub)) {
                    const c = dp[i - L] + m.get(sub);
                    if (c < dp[i]) dp[i] = c;
                }
            }
        }
    }
    return dp[n] === Infinity ? -1 : dp[n];
};
